# -----------------------------------------------------------------------------
# Exception Chaining (PEP 3134)
# -----------------------------------------------------------------------------

class TestExceptionChaining:
    """Verify __cause__ and __context__ behavior."""

    def test_explicit_chaining(self, sample_messages, sample_cause):
        """Explicit 'from' should set __cause__."""
        try:
            try:
                raise sample_cause
            except ValueError as cause:
                raise ParsingError(sample_messages["parsing"]) from cause
        except ParsingError as exc:
            assert exc.__cause__ is sample_cause
            assert exc.__cause__.__class__ is ValueError

    def test_implicit_chaining(self, sample_messages, sample_cause):
        """Implicit chaining should set __context__."""
        try:
            try:
                raise sample_cause
            except ValueError:
                raise ConvergenceError(sample_messages["convergence"])
        except ConvergenceError as exc:
            assert exc.__context__ is not None
            assert exc.__context__.__class__ is ValueError

    def test_chaining_suppression(self, sample_messages, sample_cause):
        """Using 'from None' should suppress chaining."""
        try:
            try:
                raise sample_cause
            except ValueError:
                raise VerificationError(sample_messages["verification"]) from None
        except VerificationError as exc:
            assert exc.__cause__ is None
            assert exc.__context__ is None

    def test_chaining_preserves_traceback(self, sample_messages, sample_cause):
        """Chained exceptions should preserve full traceback."""
        import traceback
        try:
            try:
                raise sample_cause
            except ValueError:
                raise ParsingError(sample_messages["parsing"]) from sample_cause
        except ParsingError:
            tb = traceback.format_exc()
            assert "ValueError" in tb
            assert "ParsingError" in tb


# -----------------------------------------------------------------------------
# Pickling (Serialization)
# -----------------------------------------------------------------------------

class TestPickling:
    """Verify exceptions can be serialized/deserialized."""

    def test_pickle_roundtrip(self, sample_messages):
        """Pickle and unpickle should preserve message and type."""
        original = ConvergenceError(sample_messages["convergence"])
        pickled = pickle.dumps(original)
        restored = pickle.loads(pickled)
        assert type(restored) is ConvergenceError
        assert str(restored) == sample_messages["convergence"]
        assert restored.args == original.args

    def test_pickle_chained_exception(self, sample_messages, sample_cause):
        """Chained exceptions should survive pickling."""
        try:
            try:
                raise sample_cause
            except ValueError:
                raise ParsingError(sample_messages["parsing"]) from sample_cause
        except ParsingError as exc:
            pickled = pickle.dumps(exc)
            restored = pickle.loads(pickled)
            assert type(restored) is ParsingError
            assert restored.__cause__ is not None
            assert restored.__cause__.__class__ is ValueError

    def test_pickle_unpicklable_cause(self):
        """Exceptions with unpicklable causes should still pickle."""
        cause = lambda: None  # lambdas are not picklable
        try:
            try:
                raise Exception("unpicklable")
            except Exception:
                raise ConvergenceError("test") from cause
        except ConvergenceError as exc:
            # Should not crash; __cause__ may be lost
            pickled = pickle.dumps(exc)
            restored = pickle.loads(pickled)
            assert type(restored) is ConvergenceError


