class TestEdgeCases:
    """Verify behavior with unusual or malicious inputs."""

    def test_empty_message(self):
        """Empty string should be accepted."""
        exc = MathSolverError("")
        assert str(exc) == ""

    def test_unicode_message(self):
        """Unicode characters should be preserved."""
        msg = "Δεν είναι δυνατή η ανάλυση της έκφρασης"
        exc = ParsingError(msg)
        assert str(exc) == msg

    def test_very_long_message(self):
        """Very long messages should not cause truncation."""
        msg = "x" * 100_000
        exc = ConvergenceError(msg)
        assert len(str(exc)) == 100_000

    def test_none_message(self):
        """None as message should be converted to string 'None'."""
        exc = VerificationError(None)
        assert str(exc) == "None"

    def test_non_string_args(self):
        """Non-string arguments should be converted to strings."""
        exc = MathSolverError(42, [1, 2, 3], {"key": "val"})
        assert str(exc) == "(42, [1, 2, 3], {'key': 'val'})"

    def test_hashability(self):
        """Exception instances should be hashable (for sets/dicts)."""
        exc1 = ParsingError("error A")
        exc2 = ParsingError("error A")
        s = {exc1, exc2}
        assert len(s) == 2  # different objects, even if same message

    def test_comparison(self):
        """Exceptions with same type and args should compare equal."""
        exc1 = ConvergenceError("timeout")
        exc2 = ConvergenceError("timeout")
        assert exc1 == exc2
        assert not (exc1 != exc2)

    def test_different_type_comparison(self):
        """Exceptions of different types should not compare equal."""
        exc1 = ParsingError("syntax")
        exc2 = ConvergenceError("syntax")
        assert exc1 != exc2


