class TestStandardLibraryIntegration:
    """Verify exceptions work with common stdlib patterns."""

    def test_suppress_context_manager(self, sample_messages):
        """contextlib.suppress should work with custom exceptions."""
        from contextlib import suppress
        with suppress(ParsingError):
            raise ParsingError(sample_messages["parsing"])
        # Should not propagate

    def test_except_star(self, sample_messages):
        """PEP 654 except* should work (Python 3.11+)."""
        import sys
        if sys.version_info < (3, 11):
            pytest.skip("except* requires Python 3.11+")
        errors = [ParsingError(sample_messages["parsing"]),
                  ConvergenceError(sample_messages["convergence"])]
        caught = []
        try:
            raise ExceptionGroup("multiple errors", errors)
        except* ParsingError as eg:
            caught.append("parsing")
        except* ConvergenceError as eg:
            caught.append("convergence")
        assert "parsing" in caught
        assert "convergence" in caught

    def test_traceback_module(self, sample_messages):
        """traceback module should format custom exceptions."""
        import traceback
        try:
            raise VerificationError(sample_messages["verification"])
        except VerificationError:
            tb_lines = traceback.format_exc().splitlines()
            assert any("VerificationError" in line for line in tb_lines)
            assert any(sample_messages["verification"] in line for line in tb_lines)

    def test_warnings_module(self, sample_messages):
        """Exceptions should be usable with warnings.warn()."""
        import warnings
        with pytest.warns(UserWarning, match=sample_messages["parsing"]):
            warnings.warn(sample_messages["parsing"], UserWarning)


